#!/bin/bash
# Serve, generate and score one Table 2 baseline row: run.sh <system> [gpus].
# Rows (vLLM servers at 0.85 GPU memory):
#   qwen3vl8b_8      Qwen3-VL-8B, 3 servers at 0.85, <= 96 images, 120 threads, smoke on 16 pairs first
#   qwen3vl8b_48     Qwen3-VL-8B, 3 servers at 0.85, <= 24 images, 120 threads
#   medgemma27b_48   MedGemma-27B, 4 servers at 0.85, <= 96 images, 160 threads, up to 3 resume passes (dead servers restarted)
#   medgemma27b_8    as medgemma27b_48 with 8 labelled slices per volume
#   medgemma4b_vol   MedGemma-1.5-4B volume input (<= 85 slices), as medgemma27b_48
#   neurovfm14b      NeuroVFM current-scan reports (one worker per GPU, 8 CPU threads each), then NeuroVFM's Qwen3-14B
#                    merges them (2 servers at 0.85, text only, 128 seqs, thinking off)
#   qwen3vl8b_ft_sf  finetune.py: 2-epoch status warm-up, 3 sf epochs, vLLM val of sf epochs 1-3 (1,000 pairs, status line cut),
#                    adapter check (status-line rate >= 0.5), pre-specified pick, test + external test, status line cut
#   copy, ours       not generated here: scripts/test.sh -> eval/score.py
# All rows: greedy, max 1,024 tokens, output-only repetition penalty 1.1, both test splits. Never score next to a running
# vLLM server. Env (defaults in brackets): VLLM [vllm], PYG [python] = vLLM env python (openai client),
# PYT [python] = trainer env (torch, neurovfm, flash-attn), PYS [python] = scoring env (RadGraph-XL, Rad-Delta), BRAINDIFF_PAIRS, BASELINE_DIR
# [checkpoints/table2_baselines], BRAINDIFF_CKPT [checkpoints], VAL_IDS, NEUROVFM_LLM (dir of the neurovfm-llm language_model snapshot).
set -u; S=${1:?usage: run.sh <system> [comma-separated gpus]}; IFS=, read -ra G <<< "${2:-0,1,2,3}"
H=$(cd "$(dirname "$0")" && pwd); VLLM=${VLLM:-vllm}; PYG=${PYG:-python}; PYT=${PYT:-python}; PYS=${PYS:-python}
CK=${BRAINDIFF_CKPT:-checkpoints}; export BASELINE_DIR=${BASELINE_DIR:-$CK/table2_baselines} BRAINDIFF_CKPT=$CK
export PYTHONPATH=$H${PYTHONPATH:+:$PYTHONPATH} HF_HUB_OFFLINE=1 OMP_NUM_THREADS=16 MKL_NUM_THREADS=16 OPENBLAS_NUM_THREADS=16 TOKENIZERS_PARALLELISM=false
T=$BASELINE_DIR; L=$T/logs; GEN="$PYG $H/generate.py"
case $S in qwen3vl8b_8|qwen3vl8b_48|medgemma27b_48|medgemma27b_8|medgemma4b_vol|neurovfm14b|qwen3vl8b_ft_sf) mkdir -p $L ;;
  copy|ours) echo "$S is not generated by run.sh: scripts/test.sh writes ours_rp110 and eval/score.py scores ours and the copy-prior row"; exit 0 ;;
  *) echo "unknown system $S"; exit 2 ;; esac
say() { echo "=== [$(date '+%a %H:%M')] $*"; }
tree() { local p=$1; echo $p; for c in $(ps -o pid= --ppid $p); do tree $c; done; }
# serve <model> <gpu> <port> <util> <max images, 0 = text only> [extra vllm args]
serve() { local m=$1 g=$2 q=$3 u=$4 n=$5; shift 5; local mm=(); [ "$n" -gt 0 ] && mm=(--limit-mm-per-prompt "{\"image\": $n}")
  CUDA_VISIBLE_DEVICES=$g nohup $VLLM serve $m --port $q --max-model-len 32768 --gpu-memory-utilization $u "${mm[@]}" --max-num-seqs 64 --api-key local \
    --logits-processors out_rep_penalty:OutputRepetitionPenalty "$@" > $L/vllm_$q.log 2>&1 < /dev/null & echo $! > $L/vllm_$q.pid; }
stop() { for q in "$@"; do local p=$(cat $L/vllm_$q.pid 2>/dev/null); [ -n "$p" ] && ps -p $p -o args= | grep -q "vllm serve" && kill $(tree $p | tr '\n' ' ') 2>/dev/null; done; sleep 30; say "stopped $*"; }
# up <ports...> -> UP = comma list of the ports that started (a failed server is skipped, not fatal)
up() { UP=""; for q in "$@"; do until grep -q "startup complete" $L/vllm_$q.log; do if grep -q "Traceback" $L/vllm_$q.log || ! kill -0 $(cat $L/vllm_$q.pid) 2>/dev/null; then say "SERVER FAILED $q (skipped)"; continue 2; fi; sleep 15; done; UP="${UP:+$UP,}$q"; done; say "servers up: $UP"; [ -n "$UP" ]; }
heal() { local m=$1 n=$2; shift 2; local i=0; up "$@" > /dev/null || true
  for q in "$@"; do kill -0 $(cat $L/vllm_$q.pid) 2>/dev/null && curl -sf -m 10 localhost:$q/health > /dev/null && { i=$((i+1)); continue; }
    kill $(tree $(cat $L/vllm_$q.pid)) 2>/dev/null; sleep 20; mv $L/vllm_$q.log $L/vllm_${q}_dead$(date +%H%M).log; say "restart $q"; serve $m ${G[$i]} $q 0.85 $n; i=$((i+1)); done
  up "$@"; }
# score <dir>: assemble onto our greedy rows ('.' for missing pairs), then eval/score.py -> <dir>/score_<split>_epoch20.*
score() { for sp in test external_test; do $PYS -m braindiff.eval.score assemble $T/$1/gen_$sp.jsonl $CK/stage2_A0_s1d_sf/gen_${sp}_epoch20.jsonl $T/$1/gen_${sp}_epoch20.jsonl
    CUDA_VISIBLE_DEVICES=${G[0]} $PYS -m braindiff.eval.score $T/$1/gen_${sp}_epoch20.jsonl > $L/score_$1_$sp.log 2>&1; done; say "SCORED $1"; touch $T/$1/SCORED; }
ports() { local b=$1 k=$2; seq -s' ' $b $((b + k - 1)); }
vlm_row() {   # vlm_row <row> <dir> <model> <util> <max images> <threads> <passes> <render args>; servers on all given GPUs
  local row=$1 d=$2 m=$3 u=$4 n=$5 th=$6 np=$7; shift 7; local P=($(ports 8400 ${#G[@]}))
  $PYG $H/generate.py render --split test external_test "$@" > $L/render_$row.log 2>&1
  for i in "${!G[@]}"; do serve $m ${G[$i]} ${P[$i]} $u $n; done; up "${P[@]}" || exit 1
  [ $row = qwen3vl8b_8 ] && { $GEN $row --split test --limit 16 --ports $UP --threads 16 >> $L/gen_$row.log 2>&1
    local r=$(python3 -c "import json;s=[json.loads(l) for l in open('$T/$d/gen_test_speed.jsonl')];print(len(s),sum(not x['generated'].strip() for x in s))")
    say "smoke $row: rows / empty = $r"; set -- $r; [ "$1" = 16 ] && [ "$2" = 0 ] || { say "SMOKE FAILED"; stop "${P[@]}"; exit 1; }; }
  for k in $(seq 1 $np); do [ $k -gt 1 ] && heal $m $n "${P[@]}"
    for sp in test external_test; do $GEN $row --split $sp --ports $UP --threads $th >> $L/gen_$row.log 2>&1; done
    local c=$(cat $T/$d/gen_test.jsonl $T/$d/gen_external_test.jsonl | wc -l); say "PASS $k $d $c / 6241"; [ $c -ge 6241 ] && break; done
  stop "${P[@]}"; score $d; }

case $S in
  qwen3vl8b_8)    vlm_row $S qwen3vl8b_imginstr_sl8img_rp110 Qwen/Qwen3-VL-8B-Instruct 0.85 96 120 1 --sl8 ;;
  qwen3vl8b_48)   vlm_row $S qwen3vl8b_imginstr_s48_rp110 Qwen/Qwen3-VL-8B-Instruct 0.85 24 120 1 --slices 48 ;;
  medgemma27b_48) vlm_row $S medgemma27b_s48_rp110 google/medgemma-27b-it 0.85 96 160 3 --slices 48 ;;
  medgemma27b_8)  vlm_row $S medgemma27b_sl8img_rp110 google/medgemma-27b-it 0.85 96 160 3 --sl8 ;;
  medgemma4b_vol) vlm_row $S medgemma_vol85_rp110 google/medgemma-1.5-4b-it 0.85 96 160 3 --vol 85 ;;
  neurovfm14b)
    for i in "${!G[@]}"; do ( for sp in test external_test; do OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 CUDA_VISIBLE_DEVICES=${G[$i]} \
      $PYT $H/generate.py neurovfm_current --split $sp --shard $i --nshards ${#G[@]} --gpu 0; done > $L/neurovfm_current_$i.log 2>&1 ) & done; wait
    say "NeuroVFM current-scan reports: $(cat $T/neurovfm/current_test_*.jsonl | wc -l) + $(cat $T/neurovfm/current_external_test_*.jsonl | wc -l)"
    P=($(ports 8232 2)); for i in 0 1; do serve ${NEUROVFM_LLM:?set NEUROVFM_LLM} ${G[$i]} ${P[$i]} 0.85 0 --served-model-name neurovfm-qwen3-14b --max-num-seqs 128; done
    up "${P[@]}" || exit 1
    for sp in test external_test; do $GEN neurovfm14b --split $sp --ports $UP >> $L/gen_$S.log 2>&1; done
    say "GEN_DONE $(cat $T/neurovfm14b_rp110/gen_test.jsonl $T/neurovfm14b_rp110/gen_external_test.jsonl | wc -l) / 6241"; stop "${P[@]}"; score neurovfm14b_rp110 ;;
  qwen3vl8b_ft_sf)
    W=$CK/qwen3vl8b_sfw; O=$CK/qwen3vl8b_sf; IDS=${VAL_IDS:-$CK/decoding_check/val1000_ids.txt}; mkdir -p $W $O
    $PYG $H/generate.py render --split train val test external_test --sl8 > $L/render_$S.log 2>&1
    train() { OMP_NUM_THREADS=4 CUDA_VISIBLE_DEVICES=$(IFS=,; echo "${G[*]}") $PYT -m torch.distributed.run --nproc_per_node ${#G[@]} --master_port 29613 $H/finetune.py train --accum 8 "$@"; }
    say "warm-up: status line only, 2 epochs"; train --out $W --epochs 2 --target status > $W/train.log 2>&1; grep -q TRAIN_DONE $W/train.log || { say "!!! WARM-UP FAILED"; exit 1; }
    train --out $O --epochs 3 --target sf --init $W/epoch2 > $O/train.log 2>&1; grep -q TRAIN_DONE $O/train.log || { say "!!! SF TRAINING FAILED"; exit 1; }
    say "sf training done: $(grep EPOCH_DONE $O/train.log | tail -1)"
    P=($(ports 8370 ${#G[@]})); d() { echo $T/qwen3vl8b_ft-sf$1_imginstr_sl8img_rp110; }
    sv() { for i in "${!G[@]}"; do serve Qwen/Qwen3-VL-8B-Instruct ${G[$i]} ${P[$i]} 0.85 96 --enable-lora --max-lora-rank 16 --max-loras 3 \
      --lora-modules sf1=$O/epoch1 sf2=$O/epoch2 sf3=$O/epoch3; done; up "${P[@]}" || exit 1; }
    sv; for k in 1 2 3; do $GEN $S --lora sf$k --split val --pairs $IDS --ports $UP --threads 160 >> $L/gen_$S.log 2>&1
      say "val sf$k: $(wc -l < $(d $k)/gen_val_sub.jsonl) / 1000; $($PYS $H/generate.py sf_strip $(d $k)/gen_val_sub.jsonl)"; done; stop "${P[@]}"
    for k in 1 2 3; do r=$(python3 -c "import json;rs=[json.loads(l) for l in open('$(d $k)/gen_val_sub.jsonl')];print(round(sum(bool(x['status_line']) for x in rs)/len(rs),3))")
      awk "BEGIN{exit !($r < 0.5)}" && { say "!!! ADAPTER CHECK FAILED: sf$k status-line rate $r"; exit 1; }; done
    for k in 1 2 3; do $PYS $H/finetune.py assemble $k; done
    for k in 1 2 3; do ( CUDA_VISIBLE_DEVICES=${G[$((k - 1))]} $PYS -m braindiff.eval.score $(d $k)/gen_val1000_epoch20.jsonl > $(d $k)/score_val1000.log 2>&1 ) & done; wait
    $PYS $H/finetune.py pick | tee $O/select.log; K=$(python3 -c "import json;print(json.load(open('$O/select.json'))['chosen_epoch'])"); say "CHOSEN sf epoch $K"
    sv; for sp in test external_test; do $GEN $S --lora sf$K --split $sp --ports $UP --threads 160 >> $L/gen_$S.log 2>&1; done; stop "${P[@]}"
    M=qwen3vl8b_ft-sf${K}_imginstr_sl8img_rp110; $PYS $H/generate.py sf_strip $T/$M/gen_test.jsonl $T/$M/gen_external_test.jsonl; score $M ;;
esac
say "ALL_DONE $S"
